import type { McqBank } from "./types";
import { mcq } from "./build";

/**
 * REG question bank, fourth batch (November 2026): six more questions per topic, chosen to
 * cover concepts the earlier batches do not. Dollar limits that change yearly are avoided.
 */
export const regBankD: McqBank = {
  "circular-230-and-practitioner-ethics": [
    mcq("Which individuals may practice before the IRS under Circular 230 because of their professional status?", [["Any paid tax return preparer", "Unenrolled preparers have only limited representation rights."], ["CPAs, attorneys and enrolled agents", "Correct — they have unlimited practice rights; enrolled actuaries and retirement plan agents have limited rights."], ["Only attorneys", "CPAs and enrolled agents may also practice."], ["Only IRS-registered firms", "Practice rights belong to individuals."]], 1, "Circular 230 grants unlimited practice rights to CPAs, attorneys and enrolled agents in good standing. Enrolled actuaries and enrolled retirement plan agents have limited practice.", "EASY", "CONCEPTUAL", ["practice before the IRS"]),
    mcq("Under Circular 230, a practitioner must exercise due diligence:", [["Only when preparing returns for corporations", "Due diligence applies to all matters before the IRS."], ["In preparing returns and other documents, and in determining the correctness of representations made to the IRS and to clients", "Correct — this is the duty in §10.22."], ["Only when the client asks", "The duty applies regardless of the client's wishes."], ["Only on audits", "It applies to all practice."]], 1, "Section 10.22 requires due diligence in preparing and filing returns and documents, and in determining the correctness of oral or written representations to the Treasury and to clients.", "EASY", "CONCEPTUAL", ["due diligence"]),
    mcq("Circular 230 provides that a practitioner must not:", [["Charge any fee for representation", "Reasonable fees are permitted."], ["Unreasonably delay the prompt disposition of any matter before the IRS", "Correct — §10.23 prohibits unreasonable delay."], ["Represent more than one taxpayer", "Multiple clients are permitted."], ["Respond to IRS requests for information", "Practitioners must respond to proper requests unless privileged."]], 1, "Practitioners may not unreasonably delay matters before the IRS and must promptly submit records or information the IRS lawfully requests, unless they believe in good faith the information is privileged.", "MEDIUM", "CONCEPTUAL", ["prompt disposition"]),
    mcq("A practitioner who prepares a client's return is asked to receive the client's refund check and cash it for a fee. Under Circular 230, the practitioner:", [["May do so with written consent", "Consent does not cure the prohibition."], ["May do so if the fee is reasonable", "The fee is not the issue."], ["May not endorse or otherwise negotiate the client's refund check", "Correct — §10.31 prohibits it."], ["May do so only for electronic refunds", "The prohibition covers checks issued to the client."]], 2, "A practitioner who prepares returns may not endorse or otherwise negotiate any check, including directing or accepting electronic transfer of refunds, issued to a client by the government in respect of a federal tax liability.", "EASY", "APPLICATION", ["refund checks"]),
    mcq("Which IRS office administers and enforces Circular 230's standards of conduct for practitioners?", [["The Taxpayer Advocate Service", "It assists taxpayers with problems."], ["The Office of Professional Responsibility", "Correct — it handles practitioner discipline."], ["The Independent Office of Appeals", "Appeals resolves tax disputes."], ["The Large Business and International division", "That division handles large taxpayers' compliance."]], 1, "The Office of Professional Responsibility investigates and pursues sanctions such as censure, suspension, disbarment and monetary penalties against practitioners.", "MEDIUM", "CONCEPTUAL", ["Office of Professional Responsibility"]),
    mcq("Under Circular 230 §10.34, a practitioner may not willfully, recklessly or through gross incompetence sign a return that:", [["Contains any position the IRS might challenge", "Positions with a reasonable basis may be taken."], ["Contains a position that lacks a reasonable basis", "Correct — among other prohibited positions."], ["Was prepared using software", "Software use is irrelevant."], ["Claims a refund", "Refund claims are permitted."]], 1, "Section 10.34 prohibits signing a return with a position that lacks a reasonable basis, is an unreasonable position, or is a willful attempt to understate liability or reckless disregard of rules.", "MEDIUM", "CONCEPTUAL", ["return positions"]),
  ],

  "irs-procedures-and-appeals": [
    mcq("An individual discovers an error on a return filed last year. Which form is used to correct it?", [["Form 4868", "That is the extension request."], ["Form 1040-X", "Correct — the amended individual return."], ["Form 843", "That is used for certain refunds and abatements, not amending income tax returns."], ["Form 1120-X", "That is for corporations."]], 1, "Individuals amend income tax returns on Form 1040-X, generally within the refund statute of limitations if claiming a refund.", "EASY", "CONCEPTUAL", ["amended returns"]),
    mcq("An individual files Form 4868 by the original due date. The extension:", [["Extends the time to file and to pay", "It does not extend the time to pay."], ["Extends the time to file by six months, but not the time to pay the tax", "Correct — interest and failure-to-pay penalties can still apply."], ["Extends the time to file by three months", "The automatic extension is six months."], ["Must be approved by the IRS before it takes effect", "It is automatic if filed properly."]], 1, "An automatic extension gives more time to file, not to pay. Tax not paid by the original due date accrues interest and may attract the failure-to-pay penalty.", "EASY", "CONCEPTUAL", ["extensions"]),
    mcq("On which grounds may the IRS accept an offer in compromise?", [["Only that the taxpayer disagrees with the law", "Disagreement with the law is not a ground."], ["Doubt as to liability, doubt as to collectibility, or to promote effective tax administration", "Correct — the three grounds."], ["Any request, if the taxpayer pays 50%", "There is no fixed percentage."], ["Only after the statute of limitations on collection expires", "After expiry, there is nothing to compromise."]], 1, "An offer in compromise settles a tax liability for less than the full amount when there is doubt as to liability, doubt as to collectibility, or when collection would create hardship or be unfair (effective tax administration).", "MEDIUM", "CONCEPTUAL", ["offers in compromise"]),
    mcq("Spouses filed jointly. One spouse understated income without the other's knowledge. The unaware spouse may seek:", [["Nothing; joint filers are always jointly liable", "Relief from joint liability is available."], ["Innocent spouse relief from joint and several liability", "Correct — if the requirements are met."], ["A new filing status for that year", "Filing status cannot be changed retroactively in this way."], ["An offer in compromise only", "Innocent spouse relief addresses this situation directly."]], 1, "Joint filers are jointly and severally liable, but innocent spouse relief can relieve a spouse who did not know, and had no reason to know, of an understatement attributable to the other spouse.", "MEDIUM", "APPLICATION", ["innocent spouse relief"]),
    mcq("After a tax is assessed, how long does the IRS generally have to collect it?", [["Three years", "Three years is the general assessment period."], ["Six years", "Six years applies to substantial omissions on assessment."], ["Ten years", "Correct — the collection statute expiration date is generally ten years from assessment."], ["No limit", "Collection is generally limited to ten years."]], 2, "The IRS generally has ten years from the date of assessment to collect, which can be extended or suspended in some circumstances, such as bankruptcy or an installment agreement.", "MEDIUM", "CONCEPTUAL", ["collection statute"]),
    mcq("Before the IRS levies on a taxpayer's property, the taxpayer is generally entitled to:", [["A jury trial", "Jury trials are only in District Court refund suits."], ["A Collection Due Process hearing with the Independent Office of Appeals", "Correct — requested after a notice of intent to levy."], ["An automatic offer in compromise", "Offers must be applied for."], ["Nothing; levies are immediate", "Notice and hearing rights apply."]], 1, "After a final notice of intent to levy (or a lien filing), the taxpayer can request a Collection Due Process hearing; Appeals' determination can be reviewed by the Tax Court.", "MEDIUM", "CONCEPTUAL", ["collection due process"]),
  ],

  "business-law-contracts": [
    mcq("After an employee retires, the employer promises to pay her $10,000 in recognition of her past service. Is the promise enforceable as a contract?", [["Yes, because her service was valuable", "Past consideration does not support a new promise."], ["No, because past consideration is not valid consideration", "Correct — consideration must be bargained for in exchange."], ["Yes, if the promise is oral", "Form is not the issue."], ["No, because she is retired", "Retirement is not the issue."]], 1, "Consideration must be bargained for in exchange for the promise. An act already performed (past consideration) cannot support a later promise.", "EASY", "APPLICATION", ["consideration"]),
    mcq("A signed written contract is intended as the parties' complete agreement. One party wants to introduce evidence of an earlier oral promise that contradicts it. Under the parol evidence rule, the evidence is:", [["Always admissible", "The rule bars contradicting prior agreements."], ["Generally inadmissible to contradict the written terms", "Correct — subject to exceptions such as fraud, mistake or later modifications."], ["Admissible if the oral promise was made by a merchant", "Merchant status does not change the rule."], ["Admissible only in criminal cases", "The rule applies to contract disputes."]], 1, "The parol evidence rule bars prior or contemporaneous oral agreements that contradict a fully integrated written contract, but not evidence of fraud, duress, mistake or later modifications.", "MEDIUM", "CONCEPTUAL", ["parol evidence rule"]),
    mcq("A construction contract requires the builder to pay $500 a day for late completion, a reasonable estimate of the owner's likely loss, which was hard to measure. This clause is:", [["An unenforceable penalty", "It is a reasonable estimate, not a penalty."], ["An enforceable liquidated damages clause", "Correct — damages were hard to estimate and the amount is reasonable."], ["Void under the statute of frauds", "The statute of frauds is unrelated."], ["Enforceable only if the owner proves actual loss", "Liquidated damages replace proof of actual loss."]], 1, "Liquidated damages are enforceable when actual damages are difficult to estimate at contracting and the amount is a reasonable forecast. A clause designed to punish is an unenforceable penalty.", "MEDIUM", "APPLICATION", ["liquidated damages"]),
    mcq("A party wants to assign its rights under a contract to a third party. Assignment is generally permitted unless it:", [["Involves money", "Rights to payment are commonly assigned."], ["Would materially change the other party's duties or risks, involves personal services, or is validly prohibited", "Correct — these are the main limits."], ["Is in writing", "Writing is not a bar."], ["Is made to a corporation", "The assignee's form is irrelevant."]], 1, "Contract rights are generally assignable, but not when assignment would materially alter the obligor's duty or risk, the contract is for personal services, or assignment is prohibited by the contract or law.", "MEDIUM", "CONCEPTUAL", ["assignment"]),
    mcq("A contract between A and B requires B to pay $5,000 directly to C, A's creditor. If B does not pay, can C sue B?", [["No, because C is not a party to the contract", "Intended beneficiaries can enforce the contract."], ["Yes, because C is an intended (creditor) beneficiary", "Correct — the contract was made to benefit C."], ["Only if C paid consideration", "Beneficiaries need not provide consideration."], ["Only if C is an incidental beneficiary", "Incidental beneficiaries cannot enforce."]], 1, "Intended beneficiaries, whom the parties meant to benefit, can enforce the contract once their rights vest. Incidental beneficiaries, who benefit only indirectly, cannot.", "MEDIUM", "APPLICATION", ["third-party beneficiaries"]),
    mcq("Under the UCC, a buyer rejects a delivery that does not conform to the contract. The time for performance has not expired. The seller may:", [["Do nothing; the contract is void", "The seller may still perform."], ["Cure by notifying the buyer and delivering conforming goods within the contract time", "Correct — the seller's right to cure."], ["Sue the buyer for rejecting", "A rightful rejection is not a breach."], ["Demand payment for the nonconforming goods", "The buyer may rightfully reject them."]], 1, "Under the perfect tender rule a buyer may reject nonconforming goods, but the seller generally may cure within the time for performance by seasonable notice and a conforming delivery.", "MEDIUM", "CONCEPTUAL", ["perfect tender", "cure"]),
  ],

  "business-law-agency-and-business-structures": [
    mcq("An agent collects payments for the principal. Under the agent's duty to account, the agent must:", [["Invest the payments for the agent's benefit", "That breaches the duty of loyalty."], ["Keep the principal's money separate and account for all money and property received", "Correct — commingling is prohibited."], ["Pay the money to whoever the third party designates", "The agent must account to the principal."], ["Deposit it in the agent's personal account", "That is commingling."]], 1, "Agents owe fiduciary duties of loyalty, obedience, reasonable care, notification and accounting, including keeping the principal's property separate.", "EASY", "CONCEPTUAL", ["agent duties"]),
    mcq("A lender is given authority to sell the borrower's property if the loan is not repaid. The borrower dies. The lender's authority:", [["Ends on the borrower's death", "An agency coupled with an interest is not ended by death."], ["Continues, because it is an agency coupled with an interest", "Correct — the agent's own interest in the property supports the power."], ["Ends unless the estate approves", "Approval is not required."], ["Ends after 30 days", "There is no such rule."]], 1, "An agency coupled with an interest exists for the agent's benefit and is not revoked by the principal's act or terminated by the principal's death or incapacity.", "HARD", "CONCEPTUAL", ["agency coupled with an interest"]),
    mcq("An ordinary agency relationship is terminated by operation of law when:", [["The agent makes a mistake", "Mistakes do not terminate agency."], ["The principal dies or becomes incapacitated", "Correct — actual authority ends, generally when the agent learns of the death."], ["The agent goes on vacation", "Vacation does not terminate agency."], ["The principal's business has a bad year", "Business results do not terminate agency."]], 1, "Agency terminates by operation of law on events such as the death or incapacity of either party, bankruptcy affecting the agency, or the subject matter becoming illegal or impossible.", "MEDIUM", "CONCEPTUAL", ["termination of agency"]),
    mcq("A court is most likely to pierce the corporate veil and hold shareholders personally liable when:", [["The corporation has a loss", "Losses alone do not justify piercing."], ["Shareholders commingle personal and corporate funds and the corporation is grossly undercapitalized", "Correct — the corporation is treated as an alter ego."], ["The corporation has only one shareholder", "Single-shareholder corporations are valid."], ["Directors make a poor business decision", "That is protected by the business judgment rule."]], 1, "Courts disregard the corporate form when it is used to commit fraud or injustice, typically with commingling, ignoring formalities and inadequate capitalization.", "MEDIUM", "APPLICATION", ["piercing the corporate veil"]),
    mcq("A shareholder asks to inspect the corporation's books and records. Generally, the shareholder may do so:", [["Never; records are confidential", "Shareholders have inspection rights."], ["For a proper purpose, on written demand", "Correct — such as investigating mismanagement or valuing shares."], ["At any time and for any reason", "A proper purpose is required."], ["Only with the directors' unanimous approval", "Approval is not required for a proper purpose."]], 1, "Shareholders may inspect corporate books and records on written demand for a proper purpose reasonably related to their interest as shareholders.", "EASY", "CONCEPTUAL", ["shareholder rights"]),
    mcq("A general partner transfers her partnership interest to an outsider. Unless the other partners agree otherwise, the transferee receives:", [["Full partner status, including management rights", "Management rights do not transfer."], ["Only the transferor's share of profits and distributions", "Correct — the transferable interest is economic only."], ["Nothing, because transfers are void", "Transfers of the economic interest are permitted."], ["The right to dissolve the partnership immediately", "The transferee cannot force dissolution in this way."]], 1, "A partner's transferable interest carries only the right to receive distributions; the transferee does not become a partner or gain management rights without the other partners' consent.", "MEDIUM", "CONCEPTUAL", ["partnership interests"]),
  ],

  "debtor-creditor-and-bankruptcy": [
    mcq("Which bankruptcy chapter lets an individual with regular income keep property and pay creditors under a court-approved plan lasting three to five years?", [["Chapter 7", "Chapter 7 is liquidation."], ["Chapter 11", "Chapter 11 is mainly for businesses, though individuals may use it."], ["Chapter 13", "Correct — adjustment of debts of an individual with regular income."], ["Chapter 15", "Chapter 15 covers cross-border cases."]], 2, "Chapter 13 lets individuals with regular income repay all or part of their debts over three to five years while keeping their property.", "EASY", "CONCEPTUAL", ["Chapter 13"]),
    mcq("A year before filing for bankruptcy, while insolvent, a debtor gave a valuable truck to a friend for a nominal price. The trustee can most likely:", [["Do nothing, because the transfer was a sale", "A transfer for less than reasonably equivalent value can be avoided."], ["Avoid the transfer as a fraudulent conveyance", "Correct — made within two years for less than reasonably equivalent value while insolvent."], ["Recover only the price paid", "The trustee can recover the truck or its value."], ["Treat it as a preferential transfer", "A preference is a payment to a creditor; the friend was not a creditor."]], 1, "A trustee can avoid transfers made within two years before filing for less than reasonably equivalent value while the debtor was insolvent, or with intent to defraud creditors.", "MEDIUM", "APPLICATION", ["fraudulent transfers"]),
    mcq("In a Chapter 7 case, exempt property is:", [["Sold by the trustee first", "Exempt property is kept by the debtor."], ["Kept by the debtor and not distributed to creditors", "Correct — such as a limited homestead or tools of the trade."], ["Given to secured creditors", "Exemption protects it from general creditors."], ["Taxed at a special rate", "Exemption is unrelated to tax."]], 1, "Debtors may keep property exempt under federal or state exemption schemes; only nonexempt property is liquidated for creditors.", "EASY", "CONCEPTUAL", ["exemptions"]),
    mcq("Under UCC Article 9, a security interest attaches when:", [["The financing statement is filed", "Filing perfects; it does not create attachment."], ["Value is given, the debtor has rights in the collateral, and there is an authenticated security agreement (or the secured party has possession or control)", "Correct — all three are required."], ["The loan is repaid", "Repayment ends the security interest."], ["The debtor defaults", "Attachment comes before default."]], 1, "Attachment makes the security interest enforceable against the debtor. Perfection, usually by filing or possession, makes it effective against third parties.", "MEDIUM", "CONCEPTUAL", ["attachment"]),
    mcq("Two lenders have perfected security interests in the same equipment, neither of them a purchase money security interest. Priority generally goes to:", [["The lender with the larger loan", "Loan size does not determine priority."], ["The lender that first filed or perfected", "Correct — the first-to-file-or-perfect rule."], ["The lender that attached last", "Earlier filing or perfection wins."], ["They share equally", "Priority is not shared."]], 1, "Between conflicting perfected security interests, priority goes to the first to file or perfect, subject to special rules for purchase money security interests.", "MEDIUM", "APPLICATION", ["priority"]),
    mcq("A debtor repays a loan from its president, an insider, eight months before filing for bankruptcy, while insolvent. The trustee can:", [["Not recover it, because it was more than 90 days before filing", "The look-back period for insiders is one year."], ["Recover it as a preferential transfer", "Correct — transfers to insiders within one year can be preferences."], ["Recover it only if the president committed fraud", "Fraud is not required for a preference."], ["Recover it only if it exceeded $100,000", "There is no such threshold."]], 1, "Preferences are transfers to creditors on account of prior debts, made while insolvent, within 90 days before filing, or within one year if the creditor is an insider.", "MEDIUM", "APPLICATION", ["preferences"]),
  ],

  "federal-tax-procedures-and-penalties": [
    mcq("Interest on a federal income tax underpayment generally:", [["Starts when the IRS sends a bill", "It runs from the original due date."], ["Runs from the return's original due date, without regard to extensions, and is compounded daily", "Correct."], ["Is waived if the taxpayer had an extension", "An extension to file does not stop interest."], ["Is deductible by individuals as an itemized deduction", "Personal interest on tax underpayments is not deductible."]], 1, "Interest on underpayments accrues from the original due date until paid, compounded daily at the federal short-term rate plus three percentage points for individuals.", "MEDIUM", "CONCEPTUAL", ["interest"]),
    mcq("A taxpayer can avoid the failure-to-file and failure-to-pay penalties by showing:", [["That the tax was eventually paid", "Late payment does not remove penalties."], ["Reasonable cause and not willful neglect", "Correct — for example, serious illness or a disaster."], ["That a preparer was hired", "Relying on a preparer to file is generally not reasonable cause."], ["That the amount was small", "Amount is not a defense."]], 1, "These penalties are waived if the failure was due to reasonable cause and not willful neglect, such as serious illness, death in the family or unavoidable circumstances.", "MEDIUM", "CONCEPTUAL", ["reasonable cause"]),
    mcq("For a return filed more than 60 days late, the minimum failure-to-file penalty is the lesser of an inflation-adjusted dollar amount or:", [["10% of the tax due", "The alternative is the full tax due."], ["50% of the tax due", "The alternative is the full tax due."], ["100% of the tax required to be shown on the return", "Correct — so the minimum never exceeds the tax due."], ["25% of the tax due", "25% is the normal maximum, not the minimum rule."]], 2, "The minimum penalty ensures a meaningful charge for very late returns, but it cannot exceed the tax required to be shown on the return.", "HARD", "CONCEPTUAL", ["failure to file"]),
    mcq("A taxpayer files a refund claim for an excessive amount without reasonable cause. The erroneous refund claim penalty is:", [["10% of the excessive amount", "The rate is higher."], ["20% of the excessive amount", "Correct — under section 6676."], ["75% of the excessive amount", "That is the civil fraud rate."], ["Not applicable to refund claims", "It applies specifically to excessive claims."]], 1, "Section 6676 imposes a 20% penalty on the excessive amount of a refund or credit claim unless the excess is due to reasonable cause.", "HARD", "CONCEPTUAL", ["erroneous refund claims"]),
    mcq("An individual files a return taking a position the courts have repeatedly called frivolous, to delay or impede tax administration. The penalty is:", [["$500", "The penalty is higher."], ["$5,000", "Correct — the section 6702 penalty for frivolous returns."], ["20% of the tax", "That is the accuracy-related penalty."], ["No penalty if the tax is paid", "The penalty applies to the frivolous filing."]], 1, "Section 6702 imposes a $5,000 penalty for frivolous tax returns or specified frivolous submissions, in addition to other penalties.", "MEDIUM", "CONCEPTUAL", ["frivolous returns"]),
    mcq("A paid tax return preparer must:", [["Keep the client's original documents permanently", "Originals belong to the client."], ["Give the taxpayer a copy of the return and keep a copy, or a list of returns prepared, for three years", "Correct — failure can lead to penalties."], ["Sign returns only if the client is present", "Presence is not required."], ["File all returns on paper", "Many preparers must e-file."]], 1, "Paid preparers must sign returns, include their identifying number, furnish a copy to the taxpayer and retain a copy or list of returns prepared for three years.", "EASY", "CONCEPTUAL", ["preparer requirements"]),
  ],

  "property-transactions-basis-and-cost-recovery": [
    mcq("A residential rental building is depreciated for tax purposes:", [["Over 39 years, straight-line, mid-month convention", "That is for nonresidential real property."], ["Over 27.5 years, straight-line, mid-month convention", "Correct."], ["Over 15 years, 150% declining balance", "That is for land improvements."], ["Over 7 years, double-declining balance", "That is for many types of equipment."]], 1, "Under MACRS, residential rental property is depreciated over 27.5 years and nonresidential real property over 39 years, both straight-line with the mid-month convention.", "EASY", "CONCEPTUAL", ["MACRS"]),
    mcq("Under MACRS, a new parking lot and fencing at a business property are generally:", [["Not depreciable, like land", "Land improvements are depreciable."], ["15-year property", "Correct — land improvements."], ["39-year property", "They are separate from the building."], ["Expensed immediately", "They are capitalized and depreciated, unless an expensing election applies."]], 1, "Land itself is not depreciable, but land improvements such as parking lots, sidewalks and fences are generally 15-year property.", "MEDIUM", "CONCEPTUAL", ["land improvements"]),
    mcq("A business elects Section 179 expensing for equipment, but the election exceeds its taxable income from active trades or businesses. The excess:", [["Is lost", "It is carried forward."], ["Creates a net operating loss", "Section 179 cannot create a loss."], ["Is carried forward to future years", "Correct — the deduction is limited to business taxable income."], ["Is refunded", "There is no refund."]], 2, "The Section 179 deduction cannot exceed taxable income from the active conduct of trades or businesses; the disallowed amount carries forward.", "MEDIUM", "CONCEPTUAL", ["Section 179"]),
    mcq("A consultant receives shares worth $8,000 from a client as payment for services. What is the consultant's basis in the shares?", [["$0", "The value was taxed as income, so it becomes basis."], ["$8,000", "Correct — fair market value, which is included in income."], ["The client's basis in the shares", "Carryover basis applies to gifts, not payment for services."], ["Half of fair market value", "There is no such rule."]], 1, "Property received for services is income equal to its fair market value, and that amount becomes the recipient's basis.", "EASY", "APPLICATION", ["basis"]),
    mcq("A taxpayer converts a personal car to business use. Its adjusted basis is $30,000 and its fair market value at conversion is $18,000. Its basis for depreciation is:", [["$30,000", "Depreciation basis is the lower of the two."], ["$18,000", "Correct — the lower of adjusted basis and fair market value at conversion."], ["$24,000", "There is no averaging."], ["$0", "Converted property is depreciable."]], 1, "Using the lower amount stops a taxpayer from depreciating a decline in value that occurred during personal use.", "MEDIUM", "APPLICATION", ["converted property"]),
    mcq("A business buys another company's assets, including a customer list and a noncompete agreement. These intangibles are amortized for tax purposes over:", [["5 years", "The period is longer."], ["10 years", "The period is longer."], ["15 years, straight-line", "Correct — Section 197 intangibles."], ["Their estimated useful lives", "Section 197 sets a fixed period."]], 2, "Acquired Section 197 intangibles, including goodwill, customer lists, noncompete agreements and trademarks, are amortized straight-line over 15 years.", "MEDIUM", "CONCEPTUAL", ["Section 197"]),
  ],

  "property-transactions-gains-losses-and-like-kind-exchanges": [
    mcq("For the year, an individual's Section 1231 gains exceed Section 1231 losses. With no recapture of prior losses, the net gain is treated as:", [["Ordinary income", "Net Section 1231 gains get capital gain treatment."], ["Long-term capital gain", "Correct — while a net loss would be ordinary."], ["Short-term capital gain", "Section 1231 assets are held more than a year."], ["Tax-exempt", "The gain is taxable."]], 1, "Section 1231 gives the best of both: a net gain is long-term capital gain, and a net loss is an ordinary loss.", "EASY", "CONCEPTUAL", ["Section 1231"]),
    mcq("This year a taxpayer has a $20,000 net Section 1231 gain. Two years ago it had a $12,000 net Section 1231 loss that has not been recaptured. How is this year's gain taxed?", [["$20,000 long-term capital gain", "Prior losses must be recaptured first."], ["$12,000 ordinary income and $8,000 long-term capital gain", "Correct — the five-year look-back rule."], ["$20,000 ordinary income", "Only the unrecaptured loss amount is ordinary."], ["$8,000 ordinary income and $12,000 capital gain", "This reverses the split."]], 1, "Net Section 1231 gains are treated as ordinary income to the extent of net Section 1231 losses deducted in the previous five years that have not been recaptured.", "HARD", "CALCULATION", ["Section 1231 look-back"]),
    mcq("An individual sells a coin collection held for three years at a gain. The maximum federal rate on this long-term gain is:", [["15%", "Collectibles have a higher maximum rate."], ["20%", "Collectibles have a higher maximum rate."], ["25%", "That is for unrecaptured Section 1250 gain."], ["28%", "Correct — the maximum rate for collectibles gain."]], 3, "Long-term gains on collectibles such as art, coins and stamps are taxed at a maximum 28% rate, rather than the usual 0%, 15% or 20%.", "MEDIUM", "CONCEPTUAL", ["collectibles"]),
    mcq("An individual sells a car used only for personal driving at a $4,000 loss. The loss is:", [["Deductible as a capital loss", "Losses on personal-use property are not deductible."], ["Deductible as an ordinary loss", "It is not deductible at all."], ["Not deductible", "Correct — losses on personal-use assets are nondeductible."], ["Deductible only against gains on other cars", "No such rule applies."]], 2, "Gains on personal-use property are taxable, but losses on it are not deductible, except certain casualty losses.", "EASY", "APPLICATION", ["personal-use property"]),
    mcq("In a like-kind exchange of real property, the other party takes over a $50,000 mortgage on the taxpayer's property, and the taxpayer takes on no debt. For the taxpayer, the debt relief is:", [["Ignored", "Relief of liabilities is treated as money received."], ["Treated as boot received", "Correct — net liability relief is boot."], ["Added to the basis of the new property without gain", "It can trigger recognized gain."], ["Treated as a loan", "It is not a loan."]], 1, "Net relief of liabilities is treated as boot received, so the taxpayer recognizes gain up to that amount (limited to the gain realized).", "MEDIUM", "APPLICATION", ["like-kind exchanges", "boot"]),
    mcq("Which asset is a capital asset in the hands of a taxpayer?", [["Inventory held for sale to customers", "Inventory is excluded from capital assets."], ["Depreciable equipment used in the taxpayer's business", "Business depreciable property is Section 1231 property."], ["Shares of stock held as an investment", "Correct — investment property is a capital asset."], ["Accounts receivable from sales of inventory", "Trade receivables are excluded."]], 2, "Section 1221 defines capital assets as all property except listed items such as inventory, depreciable or real property used in a business, trade receivables and certain self-created works.", "EASY", "CONCEPTUAL", ["capital assets"]),
  ],

  "individual-taxation-gross-income": [
    mcq("A taxpayer paid $30,000 for an annuity that will pay $5,000 a year. The expected return is $50,000. How much of each payment is excluded from gross income?", [["$5,000", "Only the return of investment is excluded."], ["$3,000", "Correct — exclusion ratio $30,000 ÷ $50,000 = 60% × $5,000."], ["$2,000", "That is the taxable portion."], ["$0", "Part of each payment is a return of investment."]], 1, "The exclusion ratio (investment ÷ expected return) is applied to each payment: 60% × $5,000 = $3,000 excluded and $2,000 taxable, until the investment is recovered.", "MEDIUM", "CALCULATION", ["annuities"]),
    mcq("A taxpayer injured in a car accident receives compensatory damages for the injury and punitive damages. Which amount is taxable?", [["Both", "Compensatory damages for physical injury are excluded."], ["Neither", "Punitive damages are taxable."], ["Only the punitive damages", "Correct — punitive damages are taxable even when related to a physical injury."], ["Only the compensatory damages", "These are excluded."]], 2, "Damages received on account of personal physical injury or sickness are excluded, but punitive damages are generally taxable.", "MEDIUM", "APPLICATION", ["damages"]),
    mcq("Income from illegal activities is:", [["Excluded from gross income", "There is no exclusion for illegal income."], ["Included in gross income", "Correct — gross income includes income from any source."], ["Taxable only if the taxpayer is convicted", "Conviction is not required."], ["Taxed only by the states", "It is federally taxable."]], 1, "Section 61 includes income from whatever source derived, so illegal income must be reported.", "EASY", "CONCEPTUAL", ["gross income"]),
    mcq("Interest on US Treasury bonds is:", [["Exempt from federal and state income tax", "It is federally taxable."], ["Subject to federal income tax but exempt from state income tax", "Correct."], ["Exempt from federal income tax but subject to state tax", "That describes most municipal bond interest, in reverse."], ["Taxable only when the bond matures", "Interest is taxed as received or accrued."]], 1, "Treasury interest is taxable for federal purposes but exempt from state and local income taxes.", "EASY", "CONCEPTUAL", ["interest income"]),
    mcq("An individual wins $10,000 at a casino and loses $3,000 on other bets during the year. How is the $10,000 reported?", [["Only the net $7,000 is included in gross income", "Winnings are reported in full."], ["The full $10,000 is included in gross income, with losses deductible separately (subject to limits) only if the taxpayer itemizes", "Correct."], ["Excluded, because gambling is a hobby", "Gambling winnings are taxable."], ["Excluded up to $5,000", "There is no such exclusion."]], 1, "Gambling winnings are included in full. Losses are an itemized deduction, limited by the rules in force for the year; they are not netted against winnings in gross income.", "MEDIUM", "APPLICATION", ["gambling"]),
    mcq("An accrual-basis landlord receives next year's rent in advance in December. For tax purposes the advance rent is:", [["Taxable next year, when earned", "Prepaid rent is taxed when received."], ["Taxable in the year received", "Correct — for both cash- and accrual-basis taxpayers."], ["Never taxable", "Rent is income."], ["Taxable only if it is refundable", "Nonrefundable advance rent is taxable when received."]], 1, "Prepaid rent is income when received, regardless of accounting method. A refundable security deposit is not income until it is kept.", "MEDIUM", "APPLICATION", ["prepaid income"]),
  ],

  "individual-taxation-adjustments-and-deductions": [
    mcq("A self-employed individual pays health insurance premiums for herself and her family. These premiums are generally:", [["An itemized medical deduction only", "Self-employed health insurance is an adjustment."], ["An adjustment for adjusted gross income, limited to net self-employment earnings", "Correct — if not eligible for an employer-subsidised plan."], ["Not deductible", "They are deductible within limits."], ["A business expense on Schedule C", "They are deducted as an adjustment, not on Schedule C."]], 1, "The self-employed health insurance deduction is an above-the-line adjustment, limited to net earnings from the business, for months the taxpayer was not eligible for a subsidised employer plan.", "MEDIUM", "CONCEPTUAL", ["self-employed health insurance"]),
    mcq("A taxpayer pays a penalty to a bank for withdrawing a certificate of deposit early. The penalty is:", [["Not deductible", "It is deductible."], ["An itemized deduction", "It is an adjustment."], ["An adjustment for adjusted gross income", "Correct — the penalty on early withdrawal of savings."], ["A capital loss", "It is not a capital loss."]], 2, "The penalty on early withdrawal of savings is an above-the-line adjustment, so it is deductible whether or not the taxpayer itemizes.", "EASY", "CONCEPTUAL", ["adjustments"]),
    mcq("An eligible individual contributes directly (not through an employer) to a health savings account. The contribution is:", [["Not deductible", "Eligible contributions are deductible."], ["An adjustment for adjusted gross income, within the annual limit", "Correct."], ["An itemized medical deduction", "It is an adjustment, not itemized."], ["Deductible only if the funds are spent", "Deductibility does not depend on spending."]], 1, "Health savings account contributions by an eligible individual covered by a high-deductible health plan are deductible above the line, within the annual limit.", "EASY", "CONCEPTUAL", ["health savings accounts"]),
    mcq("A full-time school teacher buys classroom supplies with her own money. Within the annual limit, the cost is:", [["An itemized deduction", "Educator expenses are an adjustment."], ["An adjustment for adjusted gross income", "Correct — the educator expense deduction."], ["Not deductible", "Eligible educators can deduct a limited amount."], ["A tax credit", "It is a deduction, not a credit."]], 1, "Eligible educators may deduct a limited amount of unreimbursed classroom expenses as an adjustment to arrive at adjusted gross income.", "EASY", "APPLICATION", ["educator expenses"]),
    mcq("Which medical expense is NOT deductible as an itemized medical deduction?", [["Prescription drugs", "These are deductible."], ["Cosmetic surgery to improve appearance, unrelated to a disease, injury or deformity", "Correct — elective cosmetic surgery is not medical care."], ["Hospital costs", "These are deductible."], ["Health insurance premiums paid with after-tax money", "These are deductible medical expenses."]], 1, "Medical care includes diagnosis, treatment and prevention of disease. Purely cosmetic procedures are excluded unless they correct a deformity from a congenital abnormality, injury or disease.", "EASY", "APPLICATION", ["medical expenses"]),
    mcq("How is the qualified business income deduction claimed?", [["As an itemized deduction", "It is not an itemized deduction."], ["As an adjustment for adjusted gross income", "It does not reduce adjusted gross income."], ["As a deduction from adjusted gross income in computing taxable income, whether or not the taxpayer itemizes", "Correct."], ["As a refundable credit", "It is a deduction."]], 2, "The qualified business income deduction reduces taxable income but not adjusted gross income, and is available to both itemizers and those taking the standard deduction.", "MEDIUM", "CONCEPTUAL", ["qualified business income"]),
  ],

  "filing-status-credits-and-amt": [
    mcq("A child is a qualifying child under the age test if, at the end of the year, the child is:", [["Under 21", "The general limit is lower."], ["Under 19, or under 24 and a full-time student, or permanently and totally disabled at any age", "Correct."], ["Under 18 only", "Students and disabled children are covered too."], ["Any age if living with the taxpayer", "Age limits apply unless disabled."]], 1, "The qualifying child age test requires the child to be younger than the taxpayer and under 19, or under 24 if a full-time student, unless permanently and totally disabled.", "EASY", "CONCEPTUAL", ["qualifying child"]),
    mcq("To claim a qualifying relative as a dependent, the taxpayer must generally:", [["Live in the same state as the relative", "Location is not the test."], ["Provide more than half of the relative's total support for the year, among other tests", "Correct — along with the gross income and relationship or household tests."], ["Be the relative's legal guardian", "Guardianship is not required."], ["Pay the relative's taxes", "That is not a test."]], 1, "A qualifying relative must meet the relationship or member-of-household test, the gross income test, and the support test (taxpayer provides more than half of support), and not be anyone's qualifying child.", "EASY", "CONCEPTUAL", ["qualifying relative"]),
    mcq("Three siblings together provide 80% of their mother's support; none provides more than half. Under a multiple support agreement, who can claim her as a dependent?", [["All three", "Only one taxpayer can claim a dependent."], ["Any one sibling who provided more than 10% of support, if the others who also provided more than 10% agree in writing", "Correct."], ["No one", "A multiple support agreement allows one to claim her."], ["Only the sibling who provided the most", "Any qualifying sibling may claim her by agreement."]], 1, "When a group provides more than half of a person's support but no one provides more than half, one member who contributed more than 10% can claim the dependent with signed statements from the others who contributed over 10%.", "MEDIUM", "APPLICATION", ["multiple support agreements"]),
    mcq("Which item is a tax preference that must be added back in computing alternative minimum taxable income?", [["Interest on private activity bonds", "Correct — generally a preference item, though most issued in 2009 and 2010 are excluded."], ["Qualified dividends", "These are taxed at the same preferential rates for AMT."], ["Charitable contributions", "These are allowed for AMT."], ["Home mortgage interest on acquisition debt", "This is generally allowed for AMT."]], 0, "Tax-exempt interest on specified private activity bonds is a preference item for AMT, as are certain depletion and intangible drilling cost amounts.", "MEDIUM", "CONCEPTUAL", ["alternative minimum tax"]),
    mcq("A married couple filing jointly wants the child and dependent care credit. Generally, both spouses must:", [["Be over 30", "There is no age requirement for the parents."], ["Have earned income, unless one is a full-time student or incapable of self-care", "Correct — expenses are limited to the lower earner's income."], ["Itemize deductions", "Itemizing is not required."], ["Have no other credits", "Other credits do not prevent it."]], 1, "Qualifying expenses are limited to the earned income of the lower-earning spouse; a full-time student or disabled spouse is treated as having deemed earned income.", "MEDIUM", "CONCEPTUAL", ["child and dependent care credit"]),
    mcq("A taxpayer supports her 70-year-old mother, who is her dependent but not a qualifying child. Which credit may be available for the mother?", [["The child tax credit", "The child tax credit is for qualifying children under 17."], ["The credit for other dependents", "Correct — a nonrefundable credit for dependents who do not qualify for the child tax credit."], ["The earned income credit", "The mother is not a qualifying child for that credit."], ["The American opportunity credit", "That is an education credit."]], 1, "The credit for other dependents is a nonrefundable credit for dependents who do not qualify for the child tax credit, such as older children and dependent parents.", "EASY", "APPLICATION", ["credit for other dependents"]),
  ],

  "retirement-plans-and-tax-planning-basics": [
    mcq("A taxpayer contributes more to an IRA than the annual limit and does not withdraw the excess. The excess contribution is subject to:", [["A one-time 10% penalty", "The penalty is an annual excise tax at a different rate."], ["A 6% excise tax for each year it remains in the account", "Correct."], ["No penalty", "Excess contributions are penalised."], ["Immediate taxation of the whole account", "Only the excess is penalised."]], 1, "Excess IRA contributions are subject to a 6% excise tax each year until corrected, for example by withdrawing the excess and its earnings by the return due date.", "MEDIUM", "CONCEPTUAL", ["excess contributions"]),
    mcq("A participant in a 401(k) plan who is age 50 or older by the end of the year may:", [["Not contribute any more", "Contributions continue."], ["Make additional catch-up contributions above the normal deferral limit", "Correct."], ["Withdraw funds without tax", "Withdrawals are generally taxable."], ["Convert the plan to an IRA automatically", "No automatic conversion occurs."]], 1, "Participants aged 50 and over may make catch-up elective deferrals above the regular limit; SECURE 2.0 adds higher catch-up limits for certain ages.", "EASY", "CONCEPTUAL", ["catch-up contributions"]),
    mcq("The saver's credit (retirement savings contributions credit) is designed to:", [["Reward high earners for saving", "It targets lower- and moderate-income taxpayers."], ["Encourage lower- and moderate-income taxpayers to contribute to retirement plans", "Correct."], ["Replace the IRA deduction", "It is in addition to any deduction."], ["Refund early withdrawal penalties", "It does not refund penalties."]], 1, "The saver's credit is a nonrefundable credit for a percentage of retirement plan or IRA contributions, available to taxpayers below income limits.", "EASY", "CONCEPTUAL", ["saver's credit"]),
    mcq("An adult child (not disabled, chronically ill or close in age) inherits a traditional IRA from a parent who died after 2019. The child must generally:", [["Take distributions over the child's life expectancy", "Stretch treatment is limited to eligible designated beneficiaries."], ["Empty the account by the end of the tenth year after the year of death", "Correct — the 10-year rule under the SECURE Act."], ["Withdraw everything within 60 days", "There is no 60-day rule."], ["Never take distributions", "Distributions are required."]], 1, "Most non-spouse designated beneficiaries must withdraw the entire inherited account within ten years; annual distributions may also be required if the owner had begun required distributions.", "MEDIUM", "APPLICATION", ["inherited IRAs"]),
    mcq("A 45-year-old converts a traditional IRA, holding only deductible contributions and earnings, to a Roth IRA. The conversion is:", [["Tax-free and penalty-free", "Converted pre-tax amounts are taxable."], ["Taxable, but not subject to the 10% additional tax", "Correct."], ["Taxable and subject to the 10% additional tax", "Conversions are not early distributions."], ["Not permitted before age 59½", "Conversions are permitted at any age."]], 1, "Amounts converted from a traditional to a Roth IRA are included in income (except basis) but are not subject to the 10% additional tax on early distributions.", "MEDIUM", "APPLICATION", ["Roth conversions"]),
    mcq("A taxpayer covered by a retirement plan at work contributes to a traditional IRA. The deduction for the contribution:", [["Is always fully allowed", "Coverage by an employer plan can limit it."], ["May be reduced or eliminated if modified adjusted gross income is above the phase-out range", "Correct."], ["Is never allowed", "It is allowed below the phase-out range."], ["Is allowed only for Roth IRAs", "Roth contributions are never deductible."]], 1, "If the taxpayer (or spouse) is an active participant in an employer plan, the traditional IRA deduction phases out above certain income levels; nondeductible contributions are still allowed.", "MEDIUM", "CONCEPTUAL", ["IRA deductions"]),
  ],

  "c-corporation-taxation": [
    mcq("A new corporation incurs $30,000 of organizational expenditures. How much may it deduct in its first year (before amortization of the remainder)?", [["$0", "A first-year deduction is allowed."], ["$5,000", "Correct — the immediate deduction is $5,000 when expenditures do not exceed $50,000."], ["$30,000", "Only a limited amount is deductible immediately."], ["$10,000", "The immediate deduction is $5,000."]], 1, "A corporation may deduct up to $5,000 of organizational expenditures, reduced dollar for dollar by the amount over $50,000; the rest is amortized over 180 months.", "MEDIUM", "CALCULATION", ["organizational expenditures"]),
    mcq("The accumulated earnings tax is imposed on a C corporation that:", [["Pays out all its earnings as dividends", "Paying dividends avoids the tax."], ["Accumulates earnings beyond the reasonable needs of the business to avoid shareholder-level tax", "Correct."], ["Has a net operating loss", "Losses do not trigger it."], ["Is owned by more than 100 shareholders", "Ownership numbers are not the test."]], 1, "The accumulated earnings tax is a penalty tax on earnings retained beyond reasonable business needs, designed to discourage avoiding dividend taxation.", "MEDIUM", "CONCEPTUAL", ["accumulated earnings tax"]),
    mcq("The personal holding company tax targets closely held corporations whose income is mainly:", [["From manufacturing", "Active business income is not the target."], ["Passive, such as dividends, interest, rents and royalties", "Correct — at least 60% of adjusted ordinary gross income."], ["From exports", "Export income is not the test."], ["Capital gains", "Capital gains are generally excluded from the test."]], 1, "A personal holding company has five or fewer individuals owning more than 50% of its stock and at least 60% of adjusted ordinary gross income from passive sources; undistributed income is taxed.", "HARD", "CONCEPTUAL", ["personal holding company"]),
    mcq("For a calendar-year C corporation, quarterly estimated tax payments are due on the 15th day of which months?", [["January, April, July and October", "That is not the corporate schedule."], ["April, June, September and December", "Correct — the 4th, 6th, 9th and 12th months of the tax year."], ["March, June, September and December", "The first installment is in the fourth month."], ["Only in December", "Payments are quarterly."]], 1, "Corporate estimated tax installments are due on the 15th day of the 4th, 6th, 9th and 12th months of the tax year.", "MEDIUM", "CONCEPTUAL", ["estimated tax"]),
    mcq("A corporation that owns 85% of another domestic corporation, and files a consolidated return with it, receives dividends from it. The dividends received deduction is:", [["50%", "That is for less than 20% ownership."], ["65%", "That is for 20% to less than 80% ownership."], ["100%", "Correct — dividends from affiliated group members qualify in full."], ["0%", "A deduction is allowed."]], 2, "The dividends received deduction is 50% (under 20% owned), 65% (20% to under 80%) and 100% for qualifying dividends from members of the same affiliated group.", "MEDIUM", "CONCEPTUAL", ["dividends received deduction"]),
    mcq("In a Section 351 exchange, a transferor receives stock and $10,000 cash for property with a basis of $40,000 and a fair value of $70,000. The transferor recognizes gain of:", [["$0", "Boot triggers gain."], ["$10,000", "Correct — gain is recognized to the extent of boot, not more than the realized gain of $30,000."], ["$30,000", "Only the boot portion is recognized."], ["$70,000", "That is the fair value."]], 1, "Section 351 defers gain except to the extent of boot received. Realized gain is $30,000; recognized gain is the $10,000 of cash.", "MEDIUM", "CALCULATION", ["Section 351", "boot"]),
  ],

  "s-corporation-taxation": [
    mcq("A calendar-year corporation wants S status to apply for the current year. It must generally file Form 2553:", [["Any time during the year", "There is a deadline for the election to apply to the current year."], ["By the 15th day of the third month of the tax year", "Correct — March 15 for a calendar-year corporation."], ["With its first tax return", "That is too late for the current year."], ["Before the corporation is formed", "It can be filed once the corporation exists."]], 1, "An S election made by the 15th day of the third month of the tax year (or at any time in the preceding year) applies to the current year, if all shareholders consent; late election relief is available in some cases.", "MEDIUM", "CONCEPTUAL", ["S election"]),
    mcq("An S corporation that has accumulated earnings and profits from C corporation years loses its S status if:", [["It has any passive income", "Some passive income is allowed."], ["Its passive investment income exceeds 25% of gross receipts for three consecutive years", "Correct."], ["It pays dividends", "S corporations make distributions, not dividends."], ["It has a loss", "Losses do not terminate the election."]], 1, "S status terminates when an S corporation with C corporation earnings and profits has passive investment income above 25% of gross receipts for three consecutive tax years.", "HARD", "CONCEPTUAL", ["termination"]),
    mcq("An S corporation pays health insurance premiums for a shareholder-employee who owns 40% of the stock. The premiums are:", [["Excluded from the shareholder's wages, like other employees", "More-than-2% shareholders are treated like partners."], ["Included in the shareholder's W-2 wages, and the shareholder may deduct them as self-employed health insurance", "Correct."], ["Not deductible by anyone", "They are deductible by the corporation and potentially the shareholder."], ["Treated as a distribution", "They are treated as wages."]], 1, "For more-than-2% shareholders, health insurance premiums paid by the S corporation are included in wages (not subject to FICA if under a plan) and may be deducted as self-employed health insurance.", "HARD", "APPLICATION", ["shareholder fringe benefits"]),
    mcq("An S corporation's sole shareholder works full-time in the business but takes only distributions and no salary. The IRS may:", [["Do nothing, because distributions are always tax-free", "Distributions can be recharacterised."], ["Recharacterise part of the distributions as wages subject to employment taxes, based on reasonable compensation", "Correct."], ["Revoke the S election immediately", "Unreasonable compensation does not terminate the election."], ["Tax the distributions as dividends", "S corporation distributions are not dividends in this way."]], 1, "Shareholder-employees must receive reasonable compensation for services, which is subject to employment taxes; the IRS can recharacterise distributions that are really wages.", "MEDIUM", "APPLICATION", ["reasonable compensation"]),
    mcq("An S corporation must generally use:", [["Any fiscal year it chooses", "Its choice is restricted."], ["A calendar year, unless it establishes a business purpose for a different year or makes a Section 444 election", "Correct."], ["The tax year of its largest customer", "Customers are irrelevant."], ["A 52-53 week year only", "That is an option, not a requirement."]], 1, "S corporations generally use a calendar year, the permitted year of most shareholders, unless they show a business purpose or make a Section 444 election with required payments.", "MEDIUM", "CONCEPTUAL", ["tax year"]),
    mcq("After an S election is terminated or revoked, how long must the corporation generally wait before re-electing S status without IRS consent?", [["One year", "The waiting period is longer."], ["Three years", "The waiting period is longer."], ["Five years", "Correct — the five-year waiting period."], ["It may never re-elect", "Re-election is possible after the waiting period."]], 2, "A corporation whose S election ends generally cannot re-elect for five tax years unless the IRS consents.", "MEDIUM", "CONCEPTUAL", ["re-election"]),
  ],

  "partnership-taxation": [
    mcq("If a partnership's partners who together own more than 50% of profits and capital share the same tax year, the partnership must generally use:", [["Any year it chooses", "Its year is determined by rules."], ["That majority-interest tax year", "Correct — the first rule in the required-year hierarchy."], ["A calendar year in all cases", "The calendar year is a fallback."], ["The tax year of the managing partner", "The majority-interest rule applies first."]], 1, "The required tax year is the majority-interest year; if none, the year of all principal partners; otherwise the year producing the least aggregate deferral, unless a business purpose or Section 444 election applies.", "MEDIUM", "CONCEPTUAL", ["tax year"]),
    mcq("A partnership with a Section 754 election in effect is affected how when a partner sells her interest at a gain?", [["Nothing changes", "The election adjusts inside basis."], ["The partnership adjusts the basis of its assets for the buying partner to reflect the price paid", "Correct — a Section 743(b) adjustment."], ["The selling partner avoids tax on the gain", "The seller still recognizes gain."], ["The partnership terminates", "A sale does not terminate the partnership."]], 1, "A Section 754 election lets the partnership adjust the inside basis of its assets for the transferee partner (Section 743(b)) and on certain distributions (Section 734(b)).", "HARD", "CONCEPTUAL", ["Section 754"]),
    mcq("A calendar-year partnership must file Form 1065 by:", [["January 31", "That is for W-2 and some 1099 forms."], ["March 15", "Correct — the 15th day of the third month after year-end."], ["April 15", "That is for individual returns."], ["October 15", "That is the extended due date."]], 1, "Partnership returns are due on the 15th day of the third month after year-end, with a six-month extension available; partners receive Schedules K-1.", "EASY", "CONCEPTUAL", ["filing deadlines"]),
    mcq("A partner contributes a capital asset held for three years in exchange for a partnership interest. The partner's holding period for the interest:", [["Starts on the contribution date", "It includes the asset's holding period."], ["Includes the holding period of the contributed asset", "Correct — a tacked holding period for capital and Section 1231 assets."], ["Is always short-term for the first year", "The holding period is tacked."], ["Depends on the partnership's tax year", "Tax year is irrelevant."]], 1, "A partner's holding period for an interest received for capital or Section 1231 assets includes the holding period of the contributed property; for cash or ordinary assets, it starts on contribution.", "MEDIUM", "CONCEPTUAL", ["holding period"]),
    mcq("Under the centralized partnership audit regime, which person has sole authority to act for the partnership in an IRS examination?", [["Each partner individually", "Partners are bound by the representative's actions."], ["The partnership representative designated by the partnership", "Correct."], ["The partnership's tax preparer automatically", "The representative must be designated."], ["The IRS chooses a partner", "The IRS designates one only if the partnership does not."]], 1, "The Bipartisan Budget Act regime requires each partnership to designate a partnership representative, who binds the partnership and its partners in the audit.", "MEDIUM", "CONCEPTUAL", ["partnership audits"]),
    mcq("A partner contributes land with a basis of $20,000 and a fair value of $50,000. Two years later the partnership sells it for $50,000. Under Section 704(c), the $30,000 gain is allocated:", [["Among all partners by profit percentage", "Built-in gain is allocated to the contributor."], ["Entirely to the contributing partner", "Correct — the pre-contribution built-in gain."], ["Half to the contributing partner", "The entire built-in gain goes to the contributor."], ["Not taxed, because the partnership held it", "The gain is taxable."]], 1, "Section 704(c) requires built-in gain or loss on contributed property to be allocated to the contributing partner, so it cannot be shifted to other partners.", "MEDIUM", "APPLICATION", ["Section 704(c)"]),
  ],

  "trusts-estates-and-gift-tax-basics": [
    mcq("A federal gift tax return (Form 709) for gifts made during a calendar year is generally due:", [["January 31 of the following year", "The due date is later."], ["April 15 of the following year", "Correct — extended if the donor extends the income tax return."], ["Nine months after the gift", "That timing applies to estate tax returns."], ["Only at death", "Returns are filed annually when required."]], 1, "Form 709 is due April 15 following the year of the gift; an extension of the donor's income tax return also extends it.", "EASY", "CONCEPTUAL", ["Form 709"]),
    mcq("A married couple elects gift splitting for the year. As a result:", [["Only the donor spouse pays gift tax", "Each spouse is treated as making half of the gifts."], ["Each spouse is treated as making half of every gift to third parties made by either spouse that year", "Correct — both must consent."], ["Gifts to each other become taxable", "Gifts between spouses use the marital deduction."], ["The annual exclusion is lost", "Each spouse uses his or her own exclusion."]], 1, "Gift splitting requires both spouses' consent and applies to all gifts to third parties during the year, letting the couple use two annual exclusions and two unified credits per donee.", "MEDIUM", "CONCEPTUAL", ["gift splitting"]),
    mcq("A deceased spouse did not use all of her exclusion amount. For the surviving spouse to use the unused amount (portability), the executor must:", [["Do nothing; it transfers automatically", "An election is required."], ["Elect portability on a timely filed estate tax return", "Correct — even if no estate tax is owed."], ["Pay a fee to the IRS", "No fee is required."], ["Transfer assets to a trust", "A trust is not required."]], 1, "The deceased spousal unused exclusion amount passes to the surviving spouse only if the executor elects portability on a timely filed Form 706, though relief for late elections may be available.", "MEDIUM", "CONCEPTUAL", ["portability"]),
    mcq("An estate must file a fiduciary income tax return (Form 1041) if its gross income for the year is at least:", [["$100", "The threshold is $600."], ["$600", "Correct."], ["$5,000", "The threshold is lower."], ["Any amount", "There is a threshold."]], 1, "An estate files Form 1041 if it has gross income of $600 or more for the tax year, or a beneficiary is a nonresident alien.", "MEDIUM", "CONCEPTUAL", ["Form 1041"]),
    mcq("A grandmother makes a large gift directly to her grandson while his parent (her child) is alive. In addition to gift tax, the transfer may be subject to:", [["The net investment income tax", "That applies to investment income."], ["The generation-skipping transfer tax", "Correct — the grandson is a skip person."], ["Self-employment tax", "Gifts are not earnings."], ["No other tax", "The generation-skipping transfer tax may apply above its exemption."]], 1, "The generation-skipping transfer tax applies to transfers to skip persons, such as grandchildren whose parent is alive, beyond the GST exemption.", "MEDIUM", "APPLICATION", ["generation-skipping transfer tax"]),
    mcq("A decedent leaves her entire estate to a qualifying public charity. The estate's charitable deduction is:", [["Limited to 50% of the estate", "There is no percentage limit."], ["Unlimited", "Correct — bequests to qualifying charities are fully deductible."], ["Limited to the annual exclusion", "The annual exclusion applies to gifts."], ["Not allowed for estates", "Estates can deduct charitable bequests."]], 1, "Bequests to qualifying charitable organizations are deductible in full in computing the taxable estate.", "EASY", "CONCEPTUAL", ["charitable deduction"]),
  ],

  "employee-benefits-and-payroll-tax": [
    mcq("By what date must an employer furnish Form W-2 to employees and file it with the Social Security Administration?", [["January 31", "Correct — for both employee copies and filing with SSA."], ["February 28", "That was the former paper filing date for SSA."], ["March 15", "That is the partnership and S corporation return date."], ["April 15", "That is the individual return date."]], 0, "Forms W-2 (and W-3) are due to employees and to the Social Security Administration by January 31 of the following year.", "EASY", "CONCEPTUAL", ["Form W-2"]),
    mcq("A business pays an independent contractor for services. The payments are reported, above the reporting threshold, on:", [["Form W-2", "W-2 is for employees."], ["Form 1099-NEC", "Correct — nonemployee compensation."], ["Form 1099-INT", "That is for interest."], ["Form 941", "That is the employer's quarterly payroll return."]], 1, "Nonemployee compensation paid to independent contractors is reported on Form 1099-NEC; no income or FICA taxes are withheld, absent backup withholding.", "EASY", "CONCEPTUAL", ["Form 1099-NEC"]),
    mcq("An employee exercises incentive stock options and holds the shares. At exercise, for regular income tax:", [["The spread is ordinary income", "That is the treatment for nonqualified options."], ["No income is recognized, though the spread is an adjustment for the alternative minimum tax", "Correct."], ["The spread is a capital gain", "No gain is recognized at exercise."], ["The employer deducts the spread", "The employer generally gets no deduction for a qualifying disposition."]], 1, "Exercising incentive stock options does not create regular taxable income, but the bargain element is an AMT adjustment. If holding periods are met, the later sale produces long-term capital gain.", "MEDIUM", "APPLICATION", ["incentive stock options"]),
    mcq("An employee exercises nonqualified stock options when the shares are worth $50 and the exercise price is $30. The employee recognizes:", [["Nothing until the shares are sold", "The spread is taxed at exercise."], ["$20 per share of ordinary compensation income", "Correct — and the employer gets a matching deduction."], ["$20 per share of capital gain", "The spread is compensation."], ["$50 per share of ordinary income", "Only the spread is income."]], 1, "For nonqualified options with no readily ascertainable value at grant, the spread at exercise is ordinary compensation income, which becomes part of the shares' basis.", "EASY", "CALCULATION", ["nonqualified stock options"]),
    mcq("Under a cafeteria plan, employees:", [["Must take all benefits in cash", "The plan offers a choice."], ["Choose between cash and qualified benefits, with the qualified benefits chosen excluded from income", "Correct — if the plan meets Section 125."], ["Pay tax on all benefits", "Qualified benefits are excluded."], ["Can choose any benefit, including tuition for dependants", "Only qualified benefits are allowed."]], 1, "A Section 125 cafeteria plan lets employees choose between taxable cash and qualified nontaxable benefits, such as health coverage and dependent care assistance.", "MEDIUM", "CONCEPTUAL", ["cafeteria plans"]),
    mcq("A company withholds income and FICA taxes from employees' pay but does not pay them to the IRS. A responsible officer who willfully failed to pay them may be personally liable for:", [["Nothing; only the company is liable", "Responsible persons can be personally liable."], ["The trust fund recovery penalty, equal to 100% of the unpaid trust fund taxes", "Correct."], ["10% of the unpaid taxes", "The penalty is 100%."], ["Only the employer's share of FICA", "The penalty covers the withheld amounts."]], 1, "Withheld income and employee FICA taxes are held in trust for the government; willful failure to pay them makes responsible persons personally liable for a penalty equal to the unpaid amount.", "MEDIUM", "CONCEPTUAL", ["trust fund recovery penalty"]),
  ],

  "exempt-organizations-basics": [
    mcq("An organization seeking recognition of exemption under Section 501(c)(3) generally applies on:", [["Form 990", "That is the annual information return."], ["Form 1023, or Form 1023-EZ if it qualifies as a small organization", "Correct."], ["Form 1024 in all cases", "Form 1024 is for other types of exempt organizations."], ["Form 8868", "That requests an extension."]], 1, "Section 501(c)(3) organizations apply on Form 1023; eligible smaller organizations may use the streamlined Form 1023-EZ.", "EASY", "CONCEPTUAL", ["recognition of exemption"]),
    mcq("A public charity pays its chief executive far more than reasonable compensation. The IRS may impose:", [["Only revocation of exemption", "Intermediate sanctions offer an alternative."], ["Excise taxes on the executive (and on managers who knowingly approved it) under the intermediate sanctions rules", "Correct — for an excess benefit transaction."], ["Unrelated business income tax", "That applies to business income, not compensation."], ["No penalty", "Excess benefits are penalised."]], 1, "Section 4958 imposes excise taxes on disqualified persons who receive excess benefits from public charities, and on organization managers who knowingly approve them.", "HARD", "APPLICATION", ["intermediate sanctions"]),
    mcq("A Section 501(c)(3) public charity that does not make the Section 501(h) election may engage in lobbying only if:", [["It spends nothing on lobbying", "Some lobbying is permitted."], ["Lobbying is not a substantial part of its activities", "Correct — the substantial part test."], ["It reports lobbying on Form 990-T", "Form 990-T is for unrelated business income."], ["The lobbying supports a candidate", "Supporting candidates is prohibited entirely."]], 1, "Charities may lobby only insubstantially; electing Section 501(h) replaces the vague substantial part test with specific expenditure limits.", "MEDIUM", "CONCEPTUAL", ["lobbying"]),
    mcq("In computing unrelated business taxable income, an exempt organization is allowed a specific deduction of:", [["$100", "The deduction is larger."], ["$1,000", "Correct."], ["$5,000", "The deduction is smaller."], ["None", "A specific deduction is allowed."]], 1, "A specific deduction of $1,000 is allowed in computing unrelated business taxable income, which is why small amounts of unrelated income produce no tax.", "EASY", "CONCEPTUAL", ["UBTI"]),
    mcq("An exempt organization buys a building with borrowed money and rents it out. The rental income is:", [["Always excluded, because rents are passive", "Debt-financed property is an exception."], ["Partly included in unrelated business taxable income, in proportion to the acquisition debt", "Correct — debt-financed income rules."], ["Fully taxable as ordinary corporate income", "Only the debt-financed portion is included."], ["Exempt if the tenant is a charity", "The test depends on debt and use."]], 1, "Income from debt-financed property is included in unrelated business taxable income in proportion to the average acquisition indebtedness, unless the property is used for the exempt purpose.", "HARD", "CONCEPTUAL", ["debt-financed income"]),
    mcq("To avoid private foundation status, a Section 501(c)(3) organization can generally show that it normally receives:", [["Most of its funds from one wealthy donor", "That suggests a private foundation."], ["More than one-third of its support from the general public, government units or other public charities", "Correct — the public support test."], ["All its income from investments", "Investment income does not show public support."], ["Grants from a private foundation only", "One private source is not public support."]], 1, "Publicly supported charities meet a public support test, typically at least one-third of total support (or 10% with facts and circumstances) from public sources over a five-year period.", "MEDIUM", "CONCEPTUAL", ["public support test"]),
  ],
};
